60		if len(results) != 1 || results[0]["ok"] != true {
61			t.Fatalf("expected one ok result, got %#v", results)
62		}
63		event := eventOf(t, results[0])
64		if event["timestamp"] != "2026-01-02T00:04:05Z" {
65			t.Fatalf("timestamp not converted to UTC RFC3339Nano: %v", event["timestamp"])
66		}
