2	
3	// CLI-level regression coverage for the "one physical line must be exactly
4	// one complete JSON object" boundary, exercised through the public entry
5	// point users actually invoke. Only space, tab, carriage return and line
6	// feed are JSON whitespace; vertical tab, form feed, no-break space and the
7	// ideographic space are content to the JSON grammar and must not be stripped
8	// away to make a line parse. A second JSON value after the object is also
9	// rejected. The same special characters stay legal inside a string and are
10	// kept in a field's value (extra for unknown fields), while the action field
11	// keeps its existing trim rule. Per-line failures are confined to their own
12	// physical line, ordinary blank lines produce no record, and a healthy
13	// read/write exits 1 (failed logs) rather than 2 (a stream fault), with
14	// stderr empty.
15	
16	import (
17		"bytes"
18		"strings"
19		"testing"
20	)
21	
22	func TestNormalizeCLIDocumentBoundaryIllegalSeparators(t *testing.T) {
23		const okLine = `{"timestamp":"2026-01-02T00:00:00Z","action":"a"}`
24	
25		// Special bytes are written as Go rune escapes so the test does not rely
26		// on invisible raw characters: nbsp/ideo are their literal UTF-8 bytes
27		// (illegal as JSON framing), while the action value spells a vertical tab
28		// as the six-character JSON escape \u000B (legal string content).
29		const (
30			nbsp = "\u00a0" // U+00A0 no-break space, literal input byte (not JSON whitespace)
31			ideo = "\u3000" // U+3000 ideographic space, literal input byte (not JSON whitespace)
32		)
33		line6 := `{"timestamp":"2026-01-02T00:00:00Z","action":"mid\u000Bx","note":"` +
